#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Shared DDS / client helpers for device_demo tests."""

from __future__ import annotations

import json
import os
import sys
from typing import Optional

import booster_robotics_sdk_python as br


def default_dds_profile_path() -> Optional[str]:
    """Robot install path; used when FASTRTPS_DEFAULT_PROFILES_FILE is unset."""
    return os.environ.get("FASTRTPS_DEFAULT_PROFILES_FILE") or (
        "/opt/booster/config/dds_configs/single-board_configs/fastdds_profile_udp_only.xml"
        if os.path.isfile(
            "/opt/booster/config/dds_configs/single-board_configs/fastdds_profile_udp_only.xml"
        )
        else None
    )


def default_network_interface() -> str:
    # On-robot (lo / 127.0.0.1) matches single-board fastdds_profile_udp_only.xml.
    # PC → robot: set BOOSTER_NET_IF to the NIC on the robot DDS subnet (e.g. eth0).
    return os.environ.get("BOOSTER_NET_IF", "lo")


def parse_network_interface(argv: list[str]) -> str:
    if len(argv) >= 2 and argv[1] and not argv[1].startswith("-"):
        return argv[1]
    return default_network_interface()


def parse_robot_name(argv: list[str]) -> Optional[str]:
    if len(argv) >= 3 and argv[2]:
        return argv[2]
    return os.environ.get("BOOSTER_ROBOT_NAME") or None


def init_channel_factory(net_if: str, domain_id: int = 0) -> None:
    profile = default_dds_profile_path()
    if profile and not os.environ.get("FASTRTPS_DEFAULT_PROFILES_FILE"):
        os.environ["FASTRTPS_DEFAULT_PROFILES_FILE"] = profile
        print(f"FASTRTPS_DEFAULT_PROFILES_FILE={profile}")
    print(f"ChannelFactory.Init(domain_id={domain_id}, iface={net_if!r})")
    br.ChannelFactory.Instance().Init(domain_id, net_if)


def create_loco_client(robot_name: Optional[str] = None) -> br.B1LocoClient:
    client = br.B1LocoClient()
    if robot_name:
        print(f"B1LocoClient.Init(robot_name={robot_name!r})")
        client.Init(robot_name)
    else:
        print("B1LocoClient.Init()")
        client.Init()
    return client


def create_camera_client(robot_name: Optional[str] = None) -> br.CameraClient:
    client = br.CameraClient()
    if robot_name:
        print(f"CameraClient.Init(robot_name={robot_name!r})")
        client.Init(robot_name)
    else:
        print("CameraClient.Init()")
        client.Init()
    return client


def print_device_info(title: str, api_id: int, info: br.DeviceInfo) -> None:
    print(f"\n{'=' * 60}")
    print(f"{title}")
    print(f"  api_id = {api_id}")
    print(f"  kind   = {info.kind}")
    print(f"{'=' * 60}")
    try:
        body = json.loads(info.to_json_str())
        print(json.dumps(body, indent=2, ensure_ascii=False))
    except json.JSONDecodeError:
        print(info.to_json_str())


def usage(script: str) -> None:
    print(
        f"Usage: {script} <networkInterface> [robotName]\n"
        f"  networkInterface  DDS NIC: lo on-robot; eth0 from PC to robot\n"
        f"  robotName         optional; or set BOOSTER_NET_IF / BOOSTER_ROBOT_NAME\n"
        f"\nExample:\n"
        f"  {script} lo\n"
        f"  {script} eth0 my_robot"
    )
